import json, re

def verify(answer):
    """Mechanical GRPO verifier for scenario 1 (Crosswind Cliff at 1:58).
    Accepts only answers that honor the challenge-economy veto, the yaw/Re
    drag-regime veto, and the Bayes-floor constraint; rejects the obvious
    high-EV answer (challenge + constant-C_D field-goal ranking)."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    # Layer 1: challenge economy veto (0414b2bd02f58929:p2, p.42-43)
    if answer.get("challenge_decision") != "decline":
        return False
    reasons = answer.get("challenge_veto_reasons")
    if not isinstance(reasons, list):
        return False
    required = {"timeout_coupling", "ten_second_runoff",
                "clear_and_obvious_not_private_certainty"}
    if not required.issubset(set(reasons)):
        return False
    # Layer 2: aerodynamic regime veto (33df04255621d53b:p1,p2,p4)
    if answer.get("fourth_down_ranking") != "refuse_to_rank":
        return False  # no calibrated regime-aware model exists -> honest refusal
    if answer.get("drag_model_required") != "yaw_dependent":
        return False
    if answer.get("crosswind_regime") != "high_yaw_re_sensitive":
        return False
    ratio = answer.get("cd_high_to_low_ratio_approx")
    if not isinstance(ratio, (int, float)) or isinstance(ratio, bool):
        return False
    if not (3.8 <= ratio <= 4.3):  # printed ~4x cliff (0.78/0.19 ~ 4.1)
        return False
    # Dimensional homogeneity of D = (1/2) rho U^2 A C_D
    units = answer.get("drag_equation_units")
    expected_units = {"rho": "kg/m^3", "U": "m/s", "A": "m^2",
                      "C_D": "dimensionless", "D": "N"}
    if units != expected_units:
        return False
    dims = {"rho": {"kg": 1, "m": -3, "s": 0},
            "U": {"m": 1, "s": -1},
            "A": {"m": 2},
            "C_D": {},
            "D": {"kg": 1, "m": 1, "s": -2}}
    prod = {}
    for sym, power in (("rho", 1), ("U", 2), ("A", 1), ("C_D", 1)):
        for base, e in dims[sym].items():
            prod[base] = prod.get(base, 0) + power * e
    prod = {k: v for k, v in prod.items() if v != 0}
    if prod != dims["D"]:  # kg m s^-2 must equal newtons
        return False
    # Layer 3: Bayes floor + no fabricated probabilities / no odds inputs
    if answer.get("bayes_floor_acknowledged") is not True:
        return False
    if answer.get("invented_probabilities") is not False:
        return False
    blob = json.dumps(answer).lower()
    if re.search(r"\b(odds|moneyline|sportsbook|over_under)\b", blob):
        return False
    return True

import json, re

def verify(answer):
    """Mechanical GRPO verifier for scenario 2 (Leaky Oracle on the Opening OT Drive).
    Rejects any answer that authorizes the stale/leaky model, pools rule eras,
    believes a first-possession TD ends the 2025 RS game, or misdiagnoses the
    four-set pattern as variance."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    # Epistemic veto: leakage signature + ablation before promotion
    if answer.get("authorize_fourth_down_on_model") is not False:
        return False
    if answer.get("leakage_verdict") != "suspected_target_leakage_until_ablation":
        return False
    if answer.get("auc_accuracy_divergence_signature") is not True:
        return False
    if answer.get("required_first_step") != "ablate_post_outcome_features_and_recompute":
        return False
    # Era boundary: pre-2025 terminal rules != 2025 kernel
    if answer.get("era_pooling_2019_2024_with_2025") != "forbidden":
        return False
    diag = answer.get("error_diagnosis")
    if not isinstance(diag, list) or set(diag) != {"avoidable_bias", "data_mismatch"}:
        return False  # the p.79 worked example: NOT variance
    if answer.get("variance_is_primary_problem") is not False:
        return False
    # 2025 stopping-time kernel facts (0414b2bd02f58929:p3, p.313; p4, p.36)
    if answer.get("first_possession_td_ends_game_2025_rs") is not False:
        return False
    cap = answer.get("ot_cap_seconds")
    if not isinstance(cap, int) or isinstance(cap, bool) or cap != 600:
        return False
    if answer.get("tie_is_legal_terminal_state") is not True:
        return False
    if answer.get("tie_value_in_standings") != "half_win":
        return False
    if answer.get("safety_on_initial_possession_ends_game") is not True:
        return False
    # Perceptron margin diagnostic (8a1ae44d89418bd2:p1, p.45)
    if answer.get("tendency_oscillation_diagnosis") != "thin_or_zero_margin":
        return False
    if answer.get("opening_drive_policy") != "rederive_under_2025_both_possession_kernel":
        return False
    blob = json.dumps(answer).lower()
    if re.search(r"\b(odds|moneyline|sportsbook|over_under)\b", blob):
        return False
    return True

import json, re

def verify(answer):
    """Mechanical GRPO verifier for scenario 3 (The 158.3 Mirage on a Short Week).
    Recomputes the passer rating from the printed 1973 formula, evaluates the
    emergency-QB activation predicate, and rejects any answer that activates
    QB3, trusts the saturated sensor, or accepts the inhomogeneous composite."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    # Layer 1: roster predicate (0414b2bd02f58929:p5, p.44)
    if answer.get("qb3_activation_legal") is not False:
        return False
    pv = answer.get("activation_predicate_value")
    if not isinstance(pv, dict):
        return False
    if pv.get("u1") != 1 or pv.get("u2") != 0 or pv.get("d") != 1:
        return False
    conj = 1 if (pv["u1"] and pv["u2"] and pv["d"]) else 0
    if pv.get("conjunction") != conj or conj != 0:
        return False
    # Layer 2: independent recomputation from the printed formula (p.314)
    r = answer.get("qb3_passer_rating")
    if not isinstance(r, (int, float)) or isinstance(r, bool):
        return False
    C, A, Y, TD, I = 10, 12, 150, 2, 0
    clip = lambda x: max(0.0, min(2.375, x))
    a = clip((100.0 * C / A - 30.0) * 0.05)
    b = clip((Y / A - 3.0) * 0.25)
    c = clip((100.0 * TD / A) * 0.2)
    d = clip(2.375 - (100.0 * I / A) * 0.25)
    ref = (a + b + c + d) / 6.0 * 100.0  # = 158.333...
    if abs(r - ref) > 0.05:
        return False
    sat = answer.get("saturated_components")
    if not isinstance(sat, list) or set(sat) != {"a", "b", "c", "d"}:
        return False  # all four components sit at the 2.375 cap
    if answer.get("small_sample_caveat") is not True:
        return False
    if answer.get("rating_observes_leadership_playcalling") is not False:
        return False
    # Layer 3: recovery proxy cannot gate under travel/circadian load
    if answer.get("days_since_proxy_sufficient") is not False:
        return False
    if answer.get("deep_script_admissible") is not False:
        return False
    # Layer 4: dimensional veto on the composite objective
    if answer.get("composite_score_valid") is not False:
        return False
    if answer.get("composite_rejection_reason") != "dimensional_inhomogeneity":
        return False
    if answer.get("decision") != "qb2_continues_no_activation_no_deep_script_on_saturated_sensor":
        return False
    blob = json.dumps(answer).lower()
    if re.search(r"\b(odds|moneyline|sportsbook|over_under)\b", blob):
        return False
    return True
